    ac=(ext(b,'patient-mrn'),str(ext(b,'patient-dob')))
    return chart,lab,ac,b
NOISE=re.compile(r'flu vaccine|lipid panel|blood pressure|BP \d|refill|appointment|no answer|left voicemail|voicemail|tdap|wellness|diet counseling',re.I)
out=open('/tmp/report.txt','w')
