    W(f"PT {pid} {p['name'][0]['text']} MRN {p['identifier'][0]['value']} DOB {p['birthDate']} {p['gender']}  EP {eid} dx={e['period']['start']}\n")
    for c in byp[pid]['Condition']:
        W(f"  DX {c['code']['text']} @{ext(c,'event-time')} by {c.get('recorder',{}).get('display')} ({c['id']})\n")
    for a in byp[pid]['AllergyIntolerance']:
        W(f"  ALLERGY {a['code']['text']} {[m['text'] for rr in a.get('reaction',[]) for m in rr['manifestation']]} ({a['id']})\n")
    for m in byp[pid]['MedicationAdministration']:
        W(f"  RX {m['effectiveDateTime'][:10]} {m['medicationCodeableConcept']['text']} {m.get('dosage',{}).get('text')} {m['status']} note={[n['text'] for n in m.get('note',[])]} ({m['id']})\n")
    for m in byp[pid]['MedicationDispense']:
        W(f"  DISP {m.get('whenHandedOver','')[:10]} {m['medicationCodeableConcept']['text']} qty={m.get('quantity',{}).get('value')} days={m.get('daysSupply',{}).get('value')} {[i['text'] for i in m.get('dosageInstruction',[])]} note={[n['text'] for n in m.get('note',[])]} ({m['id']})\n")
    for s in byp[pid]['Specimen']:
        o=[x for x in obs if x.get('specimen',{}).get('reference','').endswith(s['id'])][0]
        chart,lab,ac,b=spec_identity(s)
        flag='' if (lab==ac==chart) else (' <<IDCONFLICT lab=%s acc=%s chart=%s'%(lab,ac,chart))
        W(f"  LAB {s['collection']['collectedDateTime'][:10]} {o['code']['text']:<38} {o['status']:<10} {str(o.get('valueString')):<16} coll={s['collection']['collector']['display']} accBy={b['author']['display']} note={[n['text'] for n in o.get('note',[])]} (O:{o['id']} S:{s['id']} B:{b['id']}){flag}\n")
    for x in obs:
        if x['subject']['reference'].endswith(pid): continue
    # results filed here but from other specimen owner
    for o in obs:
        if not o['subject']['reference'].endswith(pid): continue
        sp=specs[o['specimen']['reference'].split('/')[-1]]
        if not sp['subject']['reference'].endswith(pid):
            W(f"  !! CROSSFILED result {o['id']} {o['code']['text']} {o.get('effectiveDateTime')[:10]} val={o.get('valueString')} specimen {sp['id']} belongs to {sp['subject']['reference']}\n")
    for doc in byp[pid]['DocumentReference']:
        txt=doc['description']
        if NOISE.search(txt) and doc['type']['text'] in ('Telephone encounter','Nursing note','Progress note') and len(txt)<200:
            W(f"  doc[{doc['type']['text']}] {doc.get('date','')[:10]} (noise) {txt.splitlines()[0][:70]} ({doc['id']})\n"); continue
        W(f"  DOC[{doc['type']['text']}] {doc.get('date','')[:10]} role={ext(doc,'author-role')} by {[a['display'] for a in doc.get('author',[])]} ({doc['id']})\n")
        for ln in txt.splitlines():
            if ln.strip(): W('       | '+ln+'\n')
out.close()
print('ok')
